-- seed.sql: destinations then tours (matches actual production schema)
-- Run against your D1 database:
--   npx wrangler d1 execute travelbyfz_db --local --file=..\..\packages\db\src\seed.sql
--   (add --remote once you're ready to seed the production database)
--
-- Safe to re-run: uses WHERE NOT EXISTS guards keyed on unique `slug` columns
-- since D1/SQLite's ON CONFLICT needs a matching unique index target, and this
-- pattern avoids relying on that if your migration hasn't created it yet.

INSERT INTO destinations (id, name, slug, state, region, short_description, description, cover_image, is_active, created_at, updated_at)
SELECT lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',abs(random())%4+1,1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6))), 'Alleppey', 'alleppey', 'Kerala', 'South India', 'Known as the Venice of the East, famous for tranquil backwater cruises on traditional houseboats.', 'Known as the Venice of the East, famous for tranquil backwater cruises on traditional houseboats.', 'https://images.unsplash.com/photo-1602216056096-3b40cc0c9944?w=600&q=80', 1, unixepoch(), unixepoch()
WHERE NOT EXISTS (SELECT 1 FROM destinations WHERE slug = 'alleppey');

