INSERT INTO tours (id, destination_id, title, slug, code, category, type, short_description, description, duration_days, duration_nights, start_location, end_location, base_price, currency, max_group_size, min_group_size, transport_included, inclusions, exclusions, highlights, featured_image, avg_rating, review_count, booking_count, is_featured, is_published, is_active, created_at, updated_at)
SELECT lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',abs(random())%4+1,1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6))), d.id, 'Golden Triangle — Delhi Agra Jaipur', 'golden-triangle', 'TBF-GOLDEN-TRI-111', 'Cultural', 'group', 'Golden Triangle — Delhi Agra Jaipur covering Delhi · Agra · Jaipur in Multi-State — a 6 day 5 night cultural experience.', 'Golden Triangle — Delhi Agra Jaipur covering Delhi · Agra · Jaipur in Multi-State — a 6 day 5 night cultural experience.', 6, 5, 'Delhi', 'Jaipur', 19500, 'INR', 12, 1, 1, '["Accommodation", "Daily breakfast", "Transport as per itinerary", "Sightseeing as listed", "Professional tour guide"]', '["Airfare/train fare", "Personal expenses", "Travel insurance", "Anything not mentioned in inclusions"]', '["Taj Mahal sunrise", "Red Fort", "City Palace Jaipur"]', 'https://images.unsplash.com/photo-1564507592333-c60657eea523?w=600&q=80', 4.8, 507, 0, 1, 1, 1, unixepoch(), unixepoch()
