INSERT INTO tours (id, destination_id, title, slug, code, category, type, short_description, description, duration_days, duration_nights, start_location, end_location, base_price, currency, max_group_size, min_group_size, transport_included, inclusions, exclusions, highlights, featured_image, avg_rating, review_count, booking_count, is_featured, is_published, is_active, created_at, updated_at)
